    const item = scores?.[key];
    if (!item || typeof item.value !== 'number' || !Number.isFinite(item.value) || item.value < 0 || item.value > 100) throw new Error(`INVALID_SCORE:${key}`);
    if(item.evidence_status!=='supported') throw new Error(`INSUFFICIENT_SCORE_EVIDENCE:${key}`);
    requireText(item.reason,`SCORE_REASON:${key}`);
    if (!Array.isArray(item.claim_ids) || !Array.isArray(item.missing_evidence)) throw new Error(`SCORE_EVIDENCE_REQUIRED:${key}`);
  }
  return scores;
}
function decideOffer(scores,evidence,override=null) {
  validateScores(scores); validateEvidence(evidence);
  const claims=new Set(evidence.claims.map(c=>c.id));
  for(const key of SCORE_KEYS) if(scores[key].claim_ids.some(id=>!claims.has(id))) throw new Error(`UNKNOWN_SCORE_CLAIM:${key}`);
  if(scores.overall.value<60) return {status:'below-threshold',reason:'Overall score below 60'};
  if(!evidence.identity_confirmed || evidence.thin || evidence.claims.length===0) return {status:'needs-review',reason:'Insufficient person-specific evidence'};
  const highest=Math.max(...Object.keys(CATEGORY).map(k=>scores[k].value));
  const winners=Object.keys(CATEGORY).filter(k=>scores[k].value===highest).map(k=>CATEGORY[k]);
  const kinds=new Set(evidence.claims.map(c=>c.kind));
  const review_reasons=[];
  let offer;
  if(override) {
    if(!['Core','Circle'].includes(override.offer)) throw new Error('INVALID_OFFER_OVERRIDE');
    requireText(override.actor,'OVERRIDE_ACTOR'); requireText(override.reason,'OVERRIDE_REASON');
    if(!Number.isFinite(Date.parse(override.at))) throw new Error('OVERRIDE_DATE_REQUIRED');
    offer=override.offer;
    review_reasons.push('Explicit reviewer offer override');
  } else {
    if(winners.length!==1) return {status:'needs-review',reason:'Category score tie',scored_pathways:winners};
    if(!['Core','Circle'].includes(winners[0])) return {status:'needs-review',reason:'Category has no approved campaign copy',scored_pathways:winners};
    if(kinds.has('board_role') || kinds.has('investing')) offer='Circle';
    else if(['executive','organization_founder','practice_owner'].some(k=>kinds.has(k))) {
      offer='Circle'; review_reasons.push('General executive/founder rule conflicts with some client Core examples; confirm this invitation');
    } else if(['specialty','research','nonprofit_leader'].some(k=>kinds.has(k))) offer='Core';
    else return {status:'needs-review',reason:'No supported offer angle',scored_pathways:winners};
  }
  if(winners.length!==1 || winners[0]!==offer) review_reasons.push('Public evidence or explicit choice differs from score ranking');
  return {status:'selected',offer,scored_pathways:winners,angle:offer==='Core'?'specialty-advisory':kinds.has('board_role')?'board-first':'deals-first',has_investing_evidence:kinds.has('investing'),review_reasons,override:override?structuredClone(override):null};
}
function assembleAndValidateCopy(lead,decision,evidence,draft) {
  validateEvidence(evidence);
  if(decision.status!=='selected') throw new Error('OFFER_NOT_SELECTED');
  const first=requireText(lead.first_name,'FIRST_NAME');
  if(/[\r\n]/.test(first)) throw new Error('INVALID_FIRST_NAME');
  const greeting=draft?.greeting_name===undefined?first:requireText(draft.greeting_name,'GREETING_NAME');
  if(greeting!==first&&!evidence.claims.some(c=>c.kind==='nickname'&&c.text===greeting))throw new Error('UNSOURCED_GREETING_NAME');
  if(/[\r\n,]/.test(greeting))throw new Error('INVALID_GREETING_NAME');
  const subject=requireText(draft?.subject,'SUBJECT');
  if(!subject.startsWith(`${greeting}, `) || /[\r\n]/.test(subject) || /reviewed (your )?(profile|resume)/i.test(subject)) throw new Error('INVALID_SUBJECT');
  if(!Array.isArray(draft.personalization) || draft.personalization.length<1 || draft.personalization.length>2) throw new Error('PERSONALIZATION_REQUIRED');
  const claimMap=new Map(evidence.claims.map(c=>[c.id,c]));
  if(!Array.isArray(draft.subject_claim_ids)||!draft.subject_claim_ids.length||draft.subject_claim_ids.some(id=>!claimMap.has(id))) throw new Error('UNSOURCED_SUBJECT');
  const usedIds=new Set(draft.subject_claim_ids);
  for(const part of draft.personalization) {
    requireText(part.text,'PERSONALIZATION_TEXT');
    if(!Array.isArray(part.claim_ids) || !part.claim_ids.length || part.claim_ids.some(id=>!claimMap.has(id))) throw new Error('UNSOURCED_PERSONALIZATION');
    part.claim_ids.forEach(id=>usedIds.add(id));
  }
  const offer=requireText(draft.offer_text,'OFFER_TEXT');
  const question=requireText(draft.closing_question,'CLOSING_QUESTION');
  if(!/\bif\b/i.test(offer)) throw new Error('CONDITIONAL_OFFER_REQUIRED');
  if(!question.endsWith('?')) throw new Error('CLOSING_QUESTION_REQUIRED');
  const body=`Hi ${greeting},\n\n${draft.personalization.map(p=>p.text.trim()).join(' ')}\n\n${offer}\n\n${question}`;
  const words=body.split(/\s+/).length;
  if(words<75 || words>110) throw new Error(`WORD_COUNT:${words}`);
  if((body.match(/\?/g)||[]).length!==1) throw new Error('EXACTLY_ONE_QUESTION_REQUIRED');
  const all=subject+'\n'+body;
  if(/[—–]/.test(all)) throw new Error('LONG_DASH');
  if(/\{\{|\}\}|\[(?:insert|name|first|last)|\b(?:undefined|null)\b/i.test(all)) throw new Error('UNRESOLVED_PLACEHOLDER');
  for(const word of BANNED) if(new RegExp(`\\b${word}\\b`,'i').test(all)) throw new Error(`FORBIDDEN_WORD:${word}`);
  if(/\b(?:I'd be happy to|rather than|not (?:simply|just)\b|clinically vetted|legacy|shape the (?:next generation|future)|you're looking for|you are looking for|we reviewed your|as we review clinical expertise)\b/i.test(all)) throw new Error('FORBIDDEN_PHRASE');
  if(/(?:^|[.!?]\s+)(?:Additionally|Furthermore|Moreover|Importantly)\b/im.test(all)) throw new Error('FORBIDDEN_SENTENCE_OPENING');
  if(/\$\s*\d|guarantee(?:d)?|you (?:will|'ll) (?:get|receive|earn)|guaranteed (?:income|returns|board)/i.test(all)) throw new Error('UNAPPROVED_PROMISE_OR_AMOUNT');
  if(decision.offer==='Circle') {
    if((offer.toLowerCase().split(VETTING.toLowerCase()).length-1)!==1) throw new Error('CIRCLE_VETTING_REQUIRED');
    if(!decision.has_investing_evidence && !/If you invest, or have thought about it/i.test(offer)) throw new Error('CONDITIONAL_INVESTING_REQUIRED');
    if(/board seat/i.test(offer) && !/something we can discuss/i.test(offer)) throw new Error('BOARD_QUALIFIER_REQUIRED');
  }
  for(const phrase of ['stood out','caught my attention','worth a look']) if(all.toLowerCase().split(phrase).length>2) throw new Error('REPEATED_PHRASE');
  if(greeting!==first)for(const c of evidence.claims.filter(c=>c.kind==='nickname'&&c.text===greeting))usedIds.add(c.id);
  const links=evidence.sources.filter(s=>[...usedIds].some(id=>claimMap.get(id).source_ids.includes(s.id)));
  return {subject,body:`${body}\n\n${SIGNATURE}`,sender:{...SENDER},offer:decision.offer,angle:decision.angle,word_count:words,claim_ids:[...usedIds],sources:links,review_reasons:[...decision.review_reasons,'Human factual and semantic review required before sending'],policy_version:POLICY_VERSION,components:{...(greeting!==first?{greeting_name:greeting}:{}),subject,subject_claim_ids:[...draft.subject_claim_ids],personalization:structuredClone(draft.personalization),offer_text:offer,closing_question:question}};
}

return {POLICY_VERSION,SENDER,SIGNATURE,VETTING,SCORE_KEYS,requireText,validateEvidence,validateScores,decideOffer,assembleAndValidateCopy};
})();
const operatingEngine=(()=>{
const {POLICY_VERSION,SCORE_KEYS,requireText,validateEvidence,decideOffer,assembleAndValidateCopy}=emailPolicy;

const ENGINE_VERSION='SAMPLE-operating-v1-2026-10-08';
const digest=value=>crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
const text=v=>typeof v==='string'?v.trim():'';
const email=v=>text(v).toLowerCase();
const validEmail=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
